【第二篇・AI 與 LLM／LAB 3】Lab 3：例句生成 CLI——第一次讓程式呼叫 AI — 步驟 5：版本二：JSON 輸出＋驗證＋降階（對照 2.8）
```
import os, sys, json
import anthropic

MODEL = "claude-sonnet-5-5"   # 最新名稱見附錄 B
PROMPT = ("為英文單字「{word}」產生學習卡內容。只回傳 JSON，不要其他文字，不要 markdown 圍欄，"
          '格式：{{"word": "...", "sentence": "...", "zh": "...", "tip": "..."}}。'
          "sentence 用 CEFR B1 難度，且必須包含該單字。")
FALLBACK = {"sentence": "Practice makes perfect.",
            "zh": "熟能生巧。", "tip": "（預設內容：AI 暫時不可用）"}

def text_of(msg):                         # 依 type 只挑文字區塊，理由同 v1
    return "".join(b.text for b in msg.content if b.type == "text")

def ask(client, word):
    msg = client.messages.create(
        model=MODEL, max_tokens=1024,     # JSON 約 150～200 token，留餘裕給可能出現的 thinking
        system="你是高中英語老師。只輸出 JSON。",
        messages=[{"role": "user", "content": PROMPT.format(word=word)}],
    )
    return text_of(msg)

def generate(word):
    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("沒有 API key，改用預設內容。", file=sys.stderr)
        return {"word": word, **FALLBACK}
    client = anthropic.Anthropic()        # 建在檢查之後，沒 key 時才接得到降階
    for attempt in range(2):              # 失敗最多重試一次
        try:
            data = json.loads(ask(client, word))
            if word.lower() in data["sentence"].lower():
                return data               # 驗證通過才放行
        except (json.JSONDecodeError, KeyError, TypeError, anthropic.APIError):
            pass
    return {"word": word, **FALLBACK}     # 降階：永遠有東西可給

if __name__ == "__main__":
    word = sys.argv[1] if len(sys.argv) > 1 else "interval"
    print(json.dumps(generate(word), ensure_ascii=False, indent=2))
```

【附錄 E・特別篇 本地端 LLM／LAB 4（沿用主線原編號）】Lab 4：本地模型上線＋斷線也不怕的切換器 — 步驟 4：切換器：一條降階容錯鏈
```
ASK = {"claude": ask_claude, "local": ask_local}   # 兩個同形的函式
CHAIN = {"claude": ["claude"], "local": ["local"],
         "auto": ["claude", "local"]}               # auto：雲端優先、本地備援

def generate(word, provider="auto"):
    for name in CHAIN[provider]:
        for attempt in range(2):
            try:
                data = json.loads(ASK[name](PROMPT.format(word=word)))
                if word.lower() in data["sentence"].lower():
                    data["by"] = name          # 記錄這筆是誰生成的
                    return data
            except Exception:
                continue                       # 這條路不通，換下一條
    return {"word": word, "by": "fallback", **FALLBACK}
```
加上命令列參數 `--provider claude|local|auto`（用 `sys.argv` 或 `argparse` 都行）。

【第三篇・開發實戰／SPRINT 1（LAB 5）】Sprint 1：MVP——今日複習佇列 — 實作 › 步驟 2：改寫 index.html
```
<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>YTP VocaBuddy</title>
<style>
  body{font-family:system-ui,sans-serif;background:#f4f6f5;margin:0;padding:24px;text-align:center}
  h1{color:#0f766e}
  #stats{color:#666;font-size:.95rem}
  #card{max-width:340px;margin:24px auto 8px;padding:36px 24px;background:#fff;border-radius:14px;
        box-shadow:0 4px 16px rgba(0,0,0,.08);font-size:2rem;user-select:none}
  #meaning{color:#0f766e;font-size:1.2rem;min-height:1.6em}
  button{margin:8px 6px 0;padding:10px 22px;font-size:1rem;border:none;border-radius:8px;
         background:#0f766e;color:#fff;cursor:pointer}
  button.warn{background:#b3403a}
</style>
</head>
<body>
<h1>YTP VocaBuddy</h1>
<p id="stats"></p>
<div id="card">—</div>
<p id="meaning">&nbsp;</p>
<div>
  <button id="reveal" onclick="reveal()">顯示答案</button>
  <button id="ok" onclick="mark(true)" hidden>記得 ✓</button>
  <button id="no" onclick="mark(false)" class="warn" hidden>忘了 ✗</button>
</div>
<script>
const WORDS = [
  {en:"algorithm", zh:"演算法"},   {en:"recursion", zh:"遞迴"},
  {en:"vocabulary", zh:"字彙"},    {en:"memorize", zh:"背誦"},
  {en:"efficient", zh:"有效率的"}, {en:"persist", zh:"堅持；持續"},
  {en:"retrieve", zh:"取回；檢索"},{en:"interval", zh:"間隔"}
];

// 學習紀錄：只屬於這台裝置，所以放 localStorage（讀寫都包 try/catch）
let log = {};
try { log = JSON.parse(localStorage.getItem("vb-log")) || {}; } catch(e){}
function save(){ try { localStorage.setItem("vb-log", JSON.stringify(log)); } catch(e){} }

let queue = [...WORDS];   // Sprint 1：每天全部複習。Sprint 3 會換成 SRS 排程
let cur = null;

const $ = id => document.getElementById(id);

function next(){
  stats();                      // 擺第一行：清空那條分支也要更新上方的計數
  if (queue.length === 0){
    $("card").textContent = "今日完成！";
    $("meaning").innerHTML = "&nbsp;";
    $("reveal").hidden = $("ok").hidden = $("no").hidden = true;
    return;
  }
  cur = queue[0];
  $("card").textContent = cur.en;
  $("meaning").innerHTML = "&nbsp;";
  $("reveal").hidden = false;
  $("ok").hidden = $("no").hidden = true;
}

function reveal(){
  $("meaning").textContent = cur.zh;
  $("reveal").hidden = true;
  $("ok").hidden = $("no").hidden = false;
}

function mark(ok){
  const s = log[cur.en] || (log[cur.en] = {seen:0, wrong:0});
  s.seen++; if (!ok) s.wrong++;
  save();
  if (ok) queue.shift();
  else queue.push(queue.shift());   // 忘了的排到今天隊尾，等一下再考一次
  next();
}

function stats(){
  $("stats").textContent = "今日佇列：剩 " + queue.length + " 張";
}

next();
</script>
</body>
</html>
```

【第三篇・開發實戰／SPRINT 2（LAB 6）】Sprint 2：AI 例句上卡片 — 實作 › 步驟 3：核心函式
```
const MODEL = "claude-sonnet-5-5";   // 最新名稱見附錄 B
const API_VERSION = "2023-06-01";    // anthropic-version 標頭值，見附錄 B

function getKey(){
  let k = null;
  try { k = localStorage.getItem("vb-key"); } catch(e){}
  if (!k){
    k = prompt("貼上你的 API key（只存在你自己的瀏覽器）");
    if (!k) return null;        // 按「取消」回的是 null，別把字串 "null" 存進去
    try { localStorage.setItem("vb-key", k); } catch(e){}
  }
  return k;
}

async function aiExample(){
  const word = cur.en, box = $("ai");
  let cache = {};
  try { cache = JSON.parse(localStorage.getItem("vb-ai")) || {}; } catch(e){}
  if (cache[word]) return show(cache[word]);        // 快取命中：不花錢、離線可用
  box.textContent = "生成中…";
  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": getKey(),
        "anthropic-version": API_VERSION,
        "anthropic-dangerous-direct-browser-access": "true"  // 瀏覽器直呼必加，見附錄 B
      },
      body: JSON.stringify({
        model: MODEL, max_tokens: 1024,        // 額度含 thinking，見 2.5
        // 注意：不要加 temperature——新模型會回 400，而且錯誤會被下面的 catch 吞掉
        system: '你是高中英語老師。只輸出 JSON：{"sentence":"...","zh":"...","tip":"..."}',
        messages: [{ role: "user",
                     content: "用單字 " + word + " 造一個 CEFR B1 例句、中譯與聯想" }]
      })
    });
    if (res.status === 401){                       // key 不對：清掉，下次自動重問
      try { localStorage.removeItem("vb-key"); } catch(e){}
      throw new Error("API key 不正確，已清除");
    }
    const data = await res.json();
    const text = data.content.filter(b => b.type === "text")   // 依 type 挑，理由見 2.5
                             .map(b => b.text).join("");
    const c = JSON.parse(text);
    if (!c.sentence.toLowerCase().includes(word.toLowerCase()))
      throw new Error("例句沒包含目標單字");
    cache[word] = c;
    try { localStorage.setItem("vb-ai", JSON.stringify(cache)); } catch(e){}
    show(c);
  } catch (e) {
    box.textContent = "AI 暫時不可用——不影響複習，例句之後再補。";
  }
  function show(c){
    box.textContent = "";                        // 模型輸出一律當「文字」，不當 HTML
    const em = document.createElement("em");
    em.textContent = c.sentence;
    box.append(em, document.createElement("br"),
               c.zh, document.createElement("br"), "聯想：" + c.tip);
  }
}
```

【第三篇・開發實戰／SPRINT 3（LAB 7）】Sprint 3：SRS 排程——你的主場到了 — 實作 › 步驟 2：寫 srs.js——先寫規則，不碰畫面
```
// srs.js —— 純函式：不碰畫面、不自己看時鐘，所以可以測試
const INTERVALS = [0, 1, 2, 4, 8, 16];   // 盒 1~5 的間隔天數（索引 0 不用）

function schedule(box, ok, today){
  const nb = ok ? Math.min(box + 1, 5) : 1;
  return { box: nb, due: today + INTERVALS[nb] };
}

// 讓 Node（測試）與瀏覽器（App）都能用這個檔案
if (typeof module !== "undefined") module.exports = { schedule, INTERVALS };
```

【第三篇・開發實戰／SPRINT 3（LAB 7）】Sprint 3：SRS 排程——你的主場到了 — 實作 › 步驟 4：接進 App：佇列改由 SRS 決定
```
// —— 日期：以「第幾天」為單位，附時間旅行測試器 ——
let dayOffset = 0;
try { dayOffset = +localStorage.getItem("vb-day") || 0; } catch(e){}
// 本地日：直接除 864e5 得到的是 UTC 日，台灣要等到早上 8 點才換日，時間旅行會看不懂
const today = () => Math.floor((Date.now() - new Date().getTimezoneOffset() * 6e4) / 864e5) + dayOffset;
window.vbTravel = n => {            // Console 輸入 vbTravel(1) 即快轉一天
  try { localStorage.setItem("vb-day", dayOffset + n); } catch(e){}
  location.reload();
};

function stateOf(w){
  const s = log[w.en] || (log[w.en] = { seen:0, wrong:0 });
  if (s.box === undefined){ s.box = 1; s.due = today(); }   // 舊紀錄自動升級
  return s;
}

let queue = WORDS.filter(w => stateOf(w).due <= today());   // 只複習「到期」的卡

function mark(ok){
  const s = stateOf(cur);
  s.seen++; if (!ok) s.wrong++;
  const r = schedule(s.box, ok, today());   // ← 排程交給純函式
  s.box = r.box; s.due = r.due;
  save();
  if (ok) queue.shift();
  else queue.push(queue.shift());
  next();
}
```
並把 `next()` 的完成訊息改成「今天沒有到期的卡——明天見！」。

