  [{ line: 1, fields: ["apple", "蘋果"] }]);                                                  // 欄位前後空白修掉
assert.deepStrictEqual(parseCSV('"give up","放棄；投降, 認輸"'),
  [{ line: 1, fields: ["give up", "放棄；投降, 認輸"] }]);                                     // 引號內的逗號不是分隔
assert.deepStrictEqual(parseCSV('"say ""hi""",打招呼'),
  [{ line: 1, fields: ['say "hi"', "打招呼"] }]);                                             // 連續兩個引號代表一個引號
